import net.neoforged.neoforge.network.registration.NetworkRegistry;
import net.neoforged.neoforge.network.ChannelBuilder;
import net.neoforged.neoforge.network.payload.KnownRegistryDataMapsPayload;

// Create a channel
var channel = ChannelBuilder.named(new ResourceLocation(MODID, "main"))
    .networkProtocolVersion(() -> "1.0")
    .optional()
    .simpleChannel();

// Register a message
channel.registerMessage(0, MyMessage.class, MyMessage::new, 
    (msg, ctx) -> { 
        ctx.enqueueWork(() -> msg.handle(ctx)); 
    });
